WITH enriched AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, LEAD(salary, 2) OVER w_running next_salary, ROW_NUMBER() OVER w_running row_seq, DENSE_RANK() OVER (PARTITION BY dept_id, job_title ORDER BY salary) salary_dense_rank, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY salary, id) event_seq FROM employees WINDOW w_running AS (ORDER BY salary, id)) SELECT s.id, s.full_name, s.dept_id, s.manager_id, s.salary, s.is_remote, s.level, s.next_salary, s.row_seq, (SELECT MAX(x.salary) FROM employees x WHERE x.manager_id = s.manager_id) AS max_employee_salary FROM enriched s ORDER BY manager_id;
